//---------------------------------------------------------------------------//
// Unit test for tools/strip
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/strip"

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Strip, LeadingSpaces)
{
  std::string s = "   abc";
  EXPECT_TRUE(strip(s, leading));
  EXPECT_EQ(s, "abc");
}

TEST(Strip, TrailingSpaces)
{
  std::string s = "abc   ";
  EXPECT_TRUE(strip(s, trailing));
  EXPECT_EQ(s, "abc");
}

TEST(Strip, BothSpaces)
{
  std::string s = "   abc   ";
  EXPECT_TRUE(strip(s, both));
  EXPECT_EQ(s, "abc");
}

TEST(Strip, NoStrippingNeeded)
{
  std::string s = "abc";
  EXPECT_FALSE(strip(s, leading));
  EXPECT_EQ(s, "abc");
  EXPECT_FALSE(strip(s, trailing));
  EXPECT_EQ(s, "abc");
  EXPECT_FALSE(strip(s, both));
  EXPECT_EQ(s, "abc");
}

TEST(Strip, AllSpaces)
{
  std::string s = "     ";
  EXPECT_TRUE(strip(s, leading));
  EXPECT_EQ(s, "");
  s = "     ";
  EXPECT_TRUE(strip(s, trailing));
  EXPECT_EQ(s, "");
  s = "     ";
  EXPECT_TRUE(strip(s, both));
  EXPECT_EQ(s, "");
}

TEST(Strip, EmptyString)
{
  std::string s = "";
  EXPECT_FALSE(strip(s, leading));
  EXPECT_EQ(s, "");
  EXPECT_FALSE(strip(s, trailing));
  EXPECT_EQ(s, "");
  EXPECT_FALSE(strip(s, both));
  EXPECT_EQ(s, "");
}

TEST(Strip, CustomChar)
{
  std::string s = "xxxabcxxx";
  EXPECT_TRUE(strip(s, leading, 'x'));
  EXPECT_EQ(s, "abcxxx");
  s = "xxxabcxxx";
  EXPECT_TRUE(strip(s, trailing, 'x'));
  EXPECT_EQ(s, "xxxabc");
  s = "xxxabcxxx";
  EXPECT_TRUE(strip(s, both, 'x'));
  EXPECT_EQ(s, "abc");
}

TEST(Strip, MixedChars)
{
  std::string s = "  \tabc\t  ";
  EXPECT_TRUE(strip(s, leading, ' '));
  EXPECT_EQ(s, "\tabc\t  ");
  s = "  \tabc\t  ";
  EXPECT_TRUE(strip(s, trailing, ' '));
  EXPECT_EQ(s, "  \tabc\t");
  s = "  \tabc\t  ";
  EXPECT_TRUE(strip(s, both, ' '));
  EXPECT_EQ(s, "\tabc\t");
}

TEST(Strip, NoMatchCustomChar)
{
  std::string s = "abc";
  EXPECT_FALSE(strip(s, leading, 'x'));
  EXPECT_EQ(s, "abc");
  EXPECT_FALSE(strip(s, trailing, 'x'));
  EXPECT_EQ(s, "abc");
  EXPECT_FALSE(strip(s, both, 'x'));
  EXPECT_EQ(s, "abc");
}

//---------------------------------------------------------------------------//
}  // namespace tools
